const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Farmland southeast of Calgary, Alberta (approximate centroid 50.8, -113.8)
  const geometry = ee.Geometry.Point([-113.75, 50.75]).buffer(5000); // 5km radius around a point
  const scale = 1000; // Use a reasonable scale to avoid memory issues for reduceRegion

  // Target dates
  const date1 = ee.Date('2025-08-19');
  const date2 = ee.Date('2025-08-24');

  // Helper function to mask clouds in Sentinel-2 images
  function maskS2Clouds(image) {
    const s2a = image.select('SCL');
    // Clouds, cloud shadows, cirrus, and optionally saturated pixels
    const masked = s2a.eq(3).or(s2a.eq(7)).or(s2a.eq(8)).or(s2a.eq(9)).or(s2a.eq(10));
    return image.updateMask(masked.not());
  }

  // Helper function to calculate NDVI
  function calculateNDVI(image) {
    return image.normalizedDifference(['B8', 'B4']).rename('NDVI');
  }

  // Function to process a single period
  async function processPeriod(targetDate, periodName) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(geometry)
      .filterDate(targetDate, targetDate.advance(1, 'day')); // Filter for the exact day

    let collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
      // Try widening the date range to +/- 2 days if no images are found on the exact day
      collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(geometry)
        .filterDate(targetDate.advance(-2, 'day'), targetDate.advance(3, 'day'));
      collectionSize = collection.size().getInfo();
    }

    if (collectionSize === 0) {
      return { ndvi: null, pixels: 0, cloudPercent: null, message: `Empty Collection for ${periodName}` };
    }

    const maskedCollection = collection.map(maskS2Clouds).map(calculateNDVI);
    const image = maskedCollection.median();

    if (image.bandNames().size().getInfo() === 0) {
      return { ndvi: null, pixels: 0, cloudPercent: null, message: `No valid image after masking for ${periodName}` };
    }

    // Calculate total pixels and valid (non-masked) pixels
    const totalPixels = image.select('NDVI').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    const validPixels = image.select('NDVI').reduceRegion({
      reducer: ee.Reducer.countDistinctNonNull(), // countNonNull for valid pixels
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    // Fallback if totalPixels is 0, prevent division by zero
    const cloudPercent = (totalPixels > 0 && validPixels !== null) ? (1 - (validPixels / totalPixels)) * 100 : 100;

    if (validPixels === null || validPixels === 0) {
      return { ndvi: null, pixels: 0, cloudPercent: cloudPercent, message: `No Valid Pixels after cloud masking for ${periodName}` };
    }

    const ndviValue = image.select('NDVI').reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    if (ndviValue === null || isNaN(ndviValue)) {
      return { ndvi: null, pixels: validPixels, cloudPercent: cloudPercent, message: `Calculation Failure for ${periodName}` };
    }

    return { ndvi: ndviValue, pixels: validPixels, cloudPercent: cloudPercent, message: `Success for ${periodName}` };
  }

  // Process both periods
  const result1 = await processPeriod(date1, 'Aug 19, 2025');
  const result2 = await processPeriod(date2, 'Aug 24, 2025');

  // 5. Validation & Final Answer
  if (result1.message.includes('Empty Collection') || result2.message.includes('Empty Collection')) {
    console.log(`Period 1: ${result1.message}, Images: ${result1.message.includes('Empty Collection') ? 0 : 'present'}`);
    console.log(`Period 2: ${result2.message}, Images: ${result2.message.includes('Empty Collection') ? 0 : 'present'}`);
    console.log("C1");
    return;
  }

  if (result1.message.includes('No Valid Pixels') || result2.message.includes('No Valid Pixels')) {
    console.log(`Aug 19, 2025: Pixels: ${result1.pixels}, Cloud: ${result1.cloudPercent.toFixed(1)}%`);
    console.log(`Aug 24, 2025: Pixels: ${result2.pixels}, Cloud: ${result2.cloudPercent.toFixed(1)}%`);
    console.log("C2");
    return;
  }

  if (result1.message.includes('Calculation Failure') || result2.message.includes('Calculation Failure')) {
    console.log(`Aug 19, 2025 NDVI: ${result1.ndvi}, Pixels: ${result1.pixels}`);
    console.log(`Aug 24, 2025 NDVI: ${result2.ndvi}, Pixels: ${result2.pixels}`);
    console.log("C3");
    return;
  }

  console.log(`Aug 19, 2025: NDVI: ${result1.ndvi.toFixed(3)}, Pixels: ${result1.pixels}, Cloud: ${result1.cloudPercent.toFixed(1)}%`);
  console.log(`Aug 24, 2025: NDVI: ${result2.ndvi.toFixed(3)}, Pixels: ${result2.pixels}, Cloud: ${result2.cloudPercent.toFixed(1)}%`);

  if (result2.ndvi < result1.ndvi) {
    console.log("A"); // Vegetation greenness decreased
  } else {
    console.log("B"); // Vegetation greenness did not decrease (stayed the same or increased)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
